solutionCode:
import { scryptSync, randomBytes, timingSafeEqual } from 'node:crypto';

export function gerarHash(senha) {
  const sal = randomBytes(16).toString('hex');
  const hash = scryptSync(senha, sal, 64).toString('hex');
  return sal + ':' + hash;
}

export function senhasEHash(senha, hash) {
  if (typeof senha !== 'string' || typeof hash !== 'string') return false;
  const partes = hash.split(':');
  if (partes.length !== 2) return false;
  const sal = partes[0];
  const hashEsperado = scryptSync(senha, sal, 64);
  const hashFornecido = Buffer.from(partes[1], 'hex');
  if (hashEsperado.length !== hashFornecido.length) return false;
  return timingSafeEqual(hashEsperado, hashFornecido);
}
